/**
 * TECH-09 (2026-10-17): the one route-count check. tests/fixtures/routes.manifest.json is generated by npm run gen
 * (scripts/gen-route-guards.mjs) from src/modules/*\/routes.ts; this test diffs the live router registry against it.
 * Added, removed or changed a route? Run `npm run gen` and commit the regenerated files (the manifest, src/routes/guards.gen.ts and,
 * if guards changed, the route-guard migration). Other tests read the total from tests/fixtures/routeManifest.ts instead of pinning it.
 */
import { describe, expect, it } from 'vitest';
import { execFileSync } from 'node:child_process';
import { ROUTES } from '../../src/routes/registry';
import { ROUTE_MANIFEST, ROUTE_MANIFEST_FILE, type ManifestGuard, type ManifestRoute } from '../fixtures/routeManifest';

const live: ManifestRoute[] = ROUTES.map((r) => {
  const g: ManifestGuard = {};
  if (r.guard.signedIn) g.signedIn = true;
  if (r.guard.anyRole) g.anyRole = [...r.guard.anyRole];
  if (r.guard.grant) g.grant = { res: r.guard.grant.res, levels: [...r.guard.grant.levels] };
  if (r.guard.noTelemetry) g.noTelemetry = true;
  return { id: r.id, path: r.path, module: r.module, zone: r.zone, guard: g };
});

describe('route manifest', () => {
  it(`the router registry equals ${ROUTE_MANIFEST_FILE} (ids, paths, modules, zones, guards, order)`, () => {
    const byId = new Map(ROUTE_MANIFEST.map((r) => [r.id, r]));
    const liveIds = new Set(live.map((r) => r.id));
    const added = live.filter((r) => !byId.has(r.id)).map((r) => `${r.id} ${r.path}`);
    const removed = ROUTE_MANIFEST.filter((r) => !liveIds.has(r.id)).map((r) => `${r.id} ${r.path}`);
    const changed = live.filter((r) => byId.has(r.id) && JSON.stringify(r) !== JSON.stringify(byId.get(r.id))).map((r) => r.id);
    const reordered = !added.length && !removed.length && live.some((r, i) => r.id !== ROUTE_MANIFEST[i].id);
    const problems = [
      added.length && `added (${added.length}): ${added.join(', ')}`,
      removed.length && `removed (${removed.length}): ${removed.join(', ')}`,
      changed.length && `changed (${changed.length}): ${changed.join(', ')}`,
      reordered && 'same routes in a different order',
    ].filter(Boolean);
    expect(
      problems,
      `The route registry (${live.length} routes) differs from ${ROUTE_MANIFEST_FILE} (${ROUTE_MANIFEST.length}). Run \`npm run gen\` and commit the regenerated files.`,
    ).toEqual([]);
    expect(live).toEqual(ROUTE_MANIFEST);
  });

  it('npm run gen leaves the manifest, guards.gen.ts and the route-guard SQL unchanged (generator --check)', () => {
    let stale = '';
    try {
      execFileSync(process.execPath, ['--no-warnings', 'scripts/gen-route-guards.mjs', '--check'], { stdio: 'pipe', encoding: 'utf8' });
    } catch (e) {
      stale = String((e as { stderr?: string }).stderr || e).trim();
    }
    expect(stale, 'Run `npm run gen` and commit the regenerated files.').toBe('');
  });
});
